+    @Test
+    public void innerCancelledBeforeOnSubscribe() throws Throwable {
+        TestHelper.withErrorTracking(errors -> {
+            for (boolean delayErrors : new boolean[] { false, true }) {
+                PublishSubject<Integer> main = PublishSubject.create();
+                PublishSubject<Integer> inner = PublishSubject.create();
+                TestObserver<Integer> to = new TestObserver<>();
+                AtomicInteger seedEmissions = new AtomicInteger();
+
+                Function<Integer, Observable<Integer>> mapper = v -> Observable.defer(() ->
+                        inner.scan(0, (a, b) -> a + b)
+                        .map(w -> {
+                            seedEmissions.incrementAndGet();
+                            return w;
+                        })
+                        .doOnSubscribe(d -> to.dispose()));
+
+                Observable<Integer> result = delayErrors
+                        ? main.switchMapDelayError(mapper) : main.switchMap(mapper);
+                result.subscribe(to);
+
+                main.onNext(1);
+
+                to.assertEmpty();
+                assertEquals(1, seedEmissions.get());
+                assertFalse(main.hasObservers());
+                assertFalse(inner.hasObservers());
+            }
+            assertTrue(errors.toString(), errors.isEmpty());
+        });
+    }
+
     @Test
